  const JN=Object.fromEntries(E.JOBS),short=(t,n)=>{const w=t.trim().split(/\s+/);return w.length>n?w.slice(0,n).join(' ')+' …':w.join(' ');},claim=(state.claim||'').trim();
  const outline=A.paras.filter(p=>p.ord!=null).map(p=>({paragraph:p.ord+1,job:JN[(state.jobs||[])[p.ord]]||'',point:((state.points||[])[p.ord]||'').trim(),opens:short(A.sents[p.sents[0]].text,16)}));
