  a.forEach((v,k)=>{const d=v.n-(b.has(k)?b.get(k).n:0);for(let i=0;i<d;i++)gone.push(v.t);});b.forEach((v,k)=>{const d=v.n-(a.has(k)?a.get(k).n:0);for(let i=0;i<d;i++)came.push(v.t);});
