function pomoSave(){store.set('ts.pomo',JSON.stringify({pat:POMO.pat,snd:POMO.snd,mode:POMO.mode,end:POMO.end,left:POMO.left,tot:POMO.tot,t0:POMO.t0,acc:POMO.acc,brk:POMO.brk,streak:POMO.streak,rounds:POMO.rounds,day:POMO.day}));}
