    b=(act,lab,tip,cls)=>'<button type="button" class="btn sm'+(cls?' '+cls:'')+'" data-pomo="'+act+'"'+tipA(tip)+'>'+lab+'</button>',lab=m.startsWith('work')?'focus':'break',long=POMO.streak>=4;
