const PBURL='https://www.phrasebank.manchester.ac.uk/',UEURL='https://www.uefap.org/';
const UEFAP={sources:['Previous research','writing-functions-41-prevres'],discuss:['Arguing and discussing','writing-functions-11-discussing'],cautious:['Expressing degrees of certainty','writing-functions-15-certainty'],cause:['Reasons and explanations','writing-functions-16-reasons'],intro:['Indicating a gap','writing-functions-42-gap']};
