const LOOK={skell:['https://skell.sketchengine.eu/',q=>'https://skell.sketchengine.eu/#result?f=concordance&lang=en&query='+encodeURIComponent(q)],linggle:['https://linggle.com/',q=>'https://linggle.com/?q='+encodeURIComponent(q)],ludwig:['https://ludwig.guru/',null]};
function lookSel(){const t=document.getElementById('wbText');return t?t.value.slice(t.selectionStart,t.selectionEnd).replace(/\s+/g,' ').trim():'';}
function lookPrep(a){const q=lookSel(),k=a.dataset.look,n=q?q.split(' ').length:0,msg=document.getElementById('lookMsg'),say=t=>{if(msg)msg.textContent=t;};a.dataset.q='';
  if(!q||n>8){a.href=LOOK[k][0];say(!q?'No words were selected, so the site opens on its front page. Select a few words in the box first.':'That is more than eight words, so the site opens on its front page. Select a shorter phrase.');return;}
  a.dataset.q=q;a.href=LOOK[k][1]?LOOK[k][1](q):LOOK[k][0];say(LOOK[k][1]?'“'+q+'” goes to the site, and is copied in case it opens without it.':'“'+q+'” is copied. Paste it into the site’s search box.');}
document.addEventListener('pointerdown',e=>{const a=e.target.closest?e.target.closest('a[data-look]'):null;if(a)lookPrep(a);});
document.addEventListener('keydown',e=>{if(e.key!=='Enter')return;const a=e.target.closest?e.target.closest('a[data-look]'):null;if(a)lookPrep(a);});
document.addEventListener('click',e=>{const a=e.target.closest?e.target.closest('a[data-look]'):null;if(!a||!a.dataset.q)return;try{navigator.clipboard.writeText(a.dataset.q).catch(()=>{});}catch(x){}});
