/* keep the rewrite box where it is on the screen when what is above it changes height as you type */
function wbHold(y0){const t=document.getElementById('wbText');if(!t||document.activeElement!==t)return;const d=t.getBoundingClientRect().top-y0;if(Math.abs(d)>=1)window.scrollBy({top:d,behavior:'instant'});}
